# 存量记录缺规格时的占位值，取当时的模板默认规格，不随后续常量调整而变
PLACEHOLDER_CPU_COUNT = 2
PLACEHOLDER_MEMORY_MB = 2048
RESOURCE_NAME_MAX_LENGTH = 63


def fill_registered_templates(apps, schema_editor):
    """旧记录是集群里手工创建的池子的登记，规格可能不全。补上占位值使其满足新的非空约束，由管理员同步前手动修正。

    须在所有表结构变更之前执行：MySQL 的 DDL 不在事务内，中途失败会留下迁移了一半的表。
    """
    E2BSandboxTemplate = apps.get_model("agent_sandbox", "E2BSandboxTemplate")
    templates = list(E2BSandboxTemplate.objects.all())

    too_long = [t.template_id for t in templates if len(t.template_id) > RESOURCE_NAME_MAX_LENGTH]
    if too_long:
        raise RuntimeError(
            f"template_id longer than {RESOURCE_NAME_MAX_LENGTH} characters can not be used as resource name: "
            f"{too_long}, rename or delete them before migrating"
        )

    for template in templates:
        filled = []
        if template.cpu_count is None:
            template.cpu_count = PLACEHOLDER_CPU_COUNT
            filled.append("cpu_count")
        if template.memory_mb is None:
            template.memory_mb = PLACEHOLDER_MEMORY_MB
            filled.append("memory_mb")
        if template.prewarm_count is None:
            template.prewarm_count = 0
            filled.append("prewarm_count")
        # 镜像无从推断，停用后 SDK 不能再用它创建沙箱
        if not template.image:
            template.enabled = False
            filled.append("enabled")
        if filled:
            template.save(update_fields=filled)
            logger.warning(
                "e2b template %s has incomplete spec, filled %s with placeholders, fix it before syncing",
                template.template_id,
                filled,
            )


